const wc = $('When Called').first().json;
let requests = [];
try { requests = JSON.parse(wc.requests_json || '[]'); } catch (e) { requests = []; }
if (!Array.isArray(requests)) requests = [];
const impact = (wc.impact || '').toString().trim();

// Primary routing row from model_routing (Lookup Routing). DB-down -> safe gemini floor: irreducible,
// since the DB read itself failed there is no row to read (mirrors Invoke Model's Resolve Routing).
let row = null;
try { const r = $('Lookup Routing').first().json; if (r && r.litellm_model) row = r; } catch (e) {}
let primary_model, primary_pin, primary_pout, primary_floor, resolution;
if (row && String(row.litellm_model).indexOf('image') >= 0) {
  primary_model = row.litellm_model;
  primary_pin = Number(row.price_in_usd_per_1k || 0);
  primary_pout = Number(row.price_out_usd_per_1k || 0);
  primary_floor = (row.fallback_price_per_unit != null) ? Number(row.fallback_price_per_unit) : null;
  resolution = row.resolution || 'high';
} else {
  primary_model = 'vertex_ai/gemini-2.5-flash-image';
  primary_pin = 0.0003; primary_pout = 0.030; primary_floor = 0.038703; resolution = 'high';
}

// All image-tier rows (Lookup Image Tiers) -> a model->prices map: the single price source for the
// fallback tier and the gpt upgrade. No tier ORDERING here (the step-down owner is Resolve Lower Tier v1).
let tiers = [];
try { tiers = $('Lookup Image Tiers').all().map(function(i){return i.json;}).filter(function(r){return r && r.litellm_model;}); } catch (e) {}
const tierByImpact = {};
for (const t of tiers) tierByImpact[t.impact] = t;
function pricesFromRow(r) { return r ? { pin: Number(r.price_in_usd_per_1k||0), pout: Number(r.price_out_usd_per_1k||0), floor: (r.fallback_price_per_unit!=null)?Number(r.fallback_price_per_unit):null } : null; }
function pricesForModel(model) { for (const t of tiers) { if (t.litellm_model === model) return pricesFromRow(t); } return null; }

// One-tier-below fallback: the MODEL + below-impact come from Resolve Lower Tier (v1) (the sole owner of
// the step-down rule, called once for the shared impact); its PRICES come from the tier map by that impact.
// floor:true (Niski has no lower tier) or a passthrough on error (no `floor` key) -> no fallback (Fire re-sends primary).
let fb = { model: '', pin: null, pout: null, floor: null };
let lower = null;
try { lower = $('Resolve Lower Tier Image').first().json; } catch (e) {}
if (lower && lower.floor === false && lower.litellm_model) {
  fb.model = lower.litellm_model;
  const bp = pricesFromRow(tierByImpact[lower.impact]);
  if (bp) { fb.pin = bp.pin; fb.pout = bp.pout; fb.floor = bp.floor; }
}

function aspectToSize(aspect, base) { if (!aspect) return base + 'x' + base; const p = String(aspect).split(':'); if (p.length !== 2) return base + 'x' + base; const w = Number(p[0]), h = Number(p[1]); if (!w || !h) return base + 'x' + base; if (w >= h) return base + 'x' + Math.round(base * h / w); return Math.round(base * w / h) + 'x' + base; }
function parseWH(s){ const p=String(s||'').toLowerCase().split('x'); const w=Number(p[0]),h=Number(p[1]); return (w&&h)?{w:w,h:h}:null; }
function gptValid(wh){ if(!wh) return false; const w=wh.w, h=wh.h; if (w%16!==0||h%16!==0) return false; const r=w/h; if (r>3||r<1/3) return false; if (Math.max(w,h)>3840) return false; const px=w*h; if (px<655360||px>8294400) return false; return true; }
function snapGptValid(wh, fallback){ if(!wh) return fallback; let w=wh.w, h=wh.h; const r=w/h; if (r>3) h=w/3; else if (r<1/3) w=h/3; const mx=Math.max(w,h); if (mx>3840){ const s=3840/mx; w*=s; h*=s; } let px=w*h; if (px<655360){ const k=Math.sqrt(655360/px)*1.02; w*=k; h*=k; } px=w*h; if (px>8294400){ const k=Math.sqrt(8294400/px); w*=k; h*=k; } const r16=function(x){return Math.max(16, Math.round(x/16)*16);}; return r16(w)+'x'+r16(h); }

const base = 1024;
const out = [];
for (const rq of requests) {
  const reqSize = (rq.size != null && String(rq.size).trim() !== '') ? String(rq.size).trim() : null;
  const aspect = (rq.aspect != null && String(rq.aspect).trim() !== '') ? String(rq.aspect).trim() : null;
  const size_requested = reqSize || (aspect ? aspectToSize(aspect, base) : (base + 'x' + base));
  let size = size_requested;
  let resolution_note = '';
  let image_model = primary_model;
  let pin = primary_pin, pout = primary_pout, floor = primary_floor;
  let isGpt = String(image_model).indexOf('openai/') === 0;
  const reqWH = parseWH(size_requested);
  const wantsShape = !!reqSize || (reqWH && reqWH.w !== reqWH.h);
  if (wantsShape && !isGpt) {
    image_model = 'openai/gpt-image-2';
    const gp = pricesForModel('openai/gpt-image-2') || { pin: 0.005, pout: 0.030, floor: 0.210805 };
    pin = gp.pin; pout = gp.pout; floor = gp.floor;
    isGpt = true;
    resolution_note = reqSize
      ? ('Aby zachować żądaną rozdzielczość ' + size_requested + ', użyto modelu OpenAI gpt-image-2 zamiast domyślnego modelu Gemini dla tego priorytetu (modele Gemini nie honorują wymuszonej rozdzielczości ani proporcji przez bramę LiteLLM).')
      : ('Aby zachować żądane proporcje obrazu (' + aspect + '), użyto modelu OpenAI gpt-image-2 zamiast domyślnego modelu Gemini dla tego priorytetu (modele Gemini nie honorują wymuszonych proporcji przez bramę LiteLLM).');
  }
  if (isGpt) {
    if (reqSize && gptValid(reqWH)) { size = size_requested; }
    else {
      size = snapGptValid(reqWH, '1024x1024');
      if (reqSize && size !== size_requested) {
        const snapMsg = 'Żądana rozdzielczość ' + size_requested + ' nie jest w pełni obsługiwana; wygenerowano w najbliższej zgodnej: ' + size + '.';
        resolution_note = resolution_note ? (resolution_note + ' ' + snapMsg) : snapMsg;
      }
    }
  }
  const image_quality = (String(image_model).indexOf('openai/') === 0) ? (resolution === 'max' ? 'high' : (resolution === 'high' ? 'medium' : 'low')) : null;
  // ADR-052 Block 3: per-provider reference transport flag. NO model-forcing — the tier's routed model
  // (incl. the pre-existing gemini->gpt-image-2 shape upgrade above) stands; we only classify how the
  // reference travels by the model already chosen. reference_urls[] is the migration seam (resolver today,
  // tool handler tomorrow). gpt-image-2 -> /v1/images/edits ('edits'); gemini -> chat-route image_url ('gemini').
  let reference_urls = Array.isArray(rq.reference_urls) ? rq.reference_urls.filter(function(u){ return u && String(u).trim() !== ''; }).map(function(u){ return String(u).trim(); }) : [];
  const use_reference = reference_urls.length > 0;
  const ref_transport = use_reference ? (isGpt ? 'edits' : 'gemini') : '';
  const ref_leg = (use_reference && ref_transport === 'edits') ? 'edits' : 'plain';
  out.push({ json: {
    placeholder_id: rq.placeholder_id || '', block_order: (rq.block_order != null) ? rq.block_order : 99,
    caption: rq.caption || '', alt: rq.alt || '', prompt: rq.prompt || '',
    primary_model: image_model, size: size, quality: image_quality, resolution_note: resolution_note,
    primary_pin: pin, primary_pout: pout, primary_floor: floor,
    fallback_model: fb.model, fallback_pin: fb.pin, fallback_pout: fb.pout, fallback_floor: fb.floor,
    use_reference: use_reference, ref_transport: ref_transport, reference_urls: reference_urls, ref_leg: ref_leg,
    impact: impact,
    clickup_task_id: wc.clickup_task_id || '', triggered_by: wc.triggered_by || 'image_gen',
    invocation_type: wc.invocation_type || 'explicit', caller_user_id: wc.caller_user_id || '', process_type: wc.process_type || ''
  } });
}
return out;

const NODE_STARTED_AT = Date.now();
// ADR-051 Block 7: internal soft-deadline that sits BELOW the n8n task-runner hard timeout
// (N8N_RUNNERS_TASK_TIMEOUT=900s). Returning partial results here BEFORE the runner kills the node
// converts a batch timeout from a thrown CRITICAL into a graceful non-blocking degrade (per un-generated
// image succeeded:false -> WARN downstream). MUST stay below the task timeout (840s < 900s).
const SOFT_DEADLINE_MS = 840000;
const PER_CALL_TIMEOUT_MS = 300000;        // gpt-image-2 ~176s/image; headroom for a large high-effort image
const MIN_REMAINING_FOR_CALL_MS = 15000;   // don't start a call (esp. a fallback) we can't hope to finish
const deadlineAt = NODE_STARTED_AT + SOFT_DEADLINE_MS;
const remaining = function(){ return deadlineAt - Date.now(); };

let key = '';
try { key = ($('Get Image Key').first().json.key || $('Get Image Key').first().json.get_litellm_image_key || ''); } catch (e) { key = ''; }
if (!key) { throw new Error('litellm_image_key missing from Vault (get_litellm_image_key returned empty) — parallel image batch cannot authenticate to LiteLLM'); }

const wc = $('When Called').first().json;
let cap = Number(wc.concurrency_cap);
if (!cap || isNaN(cap) || cap < 1) cap = 4;

const requests = $input.all().map(function(i){ return i.json; });
if (!requests.length) return [];

const { httpRequest } = this.helpers;
let inFlight = 0, maxInFlight = 0;

const callImage = async function(model, req) {
  try {
    const res = await httpRequest({
      method: 'POST',
      url: 'http://litellm:4000/v1/images/generations',
      headers: { Authorization: 'Bearer ' + key },
      body: Object.assign({ model: model, prompt: req.prompt, size: req.size, n: 1 }, req.quality ? { quality: req.quality } : {}),
      json: true,
      returnFullResponse: true,
      timeout: Math.max(5000, Math.min(PER_CALL_TIMEOUT_MS, remaining()))
    });
    const sc = res.statusCode || 200;
    const data = (res.body && res.body.data) ? res.body.data : null;
    const b64 = (data && data[0] && data[0].b64_json) ? data[0].b64_json : null;
    return { ok: sc >= 200 && sc < 300 && !!b64, statusCode: sc, b64: b64, headers: res.headers || {}, body: res.body || {} };
  } catch (e) {
    const sc = (e && (e.statusCode || e.httpCode || (e.response && e.response.statusCode))) || 0;
    const msg = (e && (e.message || (e.error && e.error.message))) || String(e);
    return { ok: false, statusCode: sc, b64: null, headers: {}, body: {}, error: msg };
  }
};

// ADR-052 Block 4a: caller-agnostic reference (image-to-image) call. Self-contained — reads only
// prompt / primary_model / reference_urls[] / ref_transport off req, so the future generate_image tool
// handler (ADR-053/054) reuses it verbatim. Returns the SAME shape as callImage {ok,statusCode,b64,
// headers,body,error} so worker() treats reference and plain results uniformly.
//   ref_transport==='gemini' -> POST /v1/chat/completions with a text part + one image_url part per
//     reference URL; the generated image returns as a data URI in
//     choices[0].message.images[0].image_url.url (Block 0 proven) -> strip the data:...;base64, prefix.
//   ref_transport==='edits' (gpt-image-2) -> multipart /v1/images/edits CANNOT be sent from a Code node:
//     n8n's httpRequest corrupts a raw multipart Buffer body, so LiteLLM rejects it 400 'Too many fields'
//     (proven by Block 0 + the Block 4 probe). So 'edits' returns ok:false + unsupported:true WITHOUT a
//     network call; worker() fails soft to plain text-to-image. Block 4b wires the edits leg via a
//     dedicated HTTP Request node sub-workflow (the only serializer that sends multipart binary intact).
const callImageReference = async function(req) {
  const urls = Array.isArray(req.reference_urls) ? req.reference_urls.filter(function(u){ return u && String(u).trim() !== ''; }).map(function(u){ return String(u).trim(); }) : [];
  if (urls.length === 0) {
    return { ok: false, unsupported: true, statusCode: 0, b64: null, headers: {}, body: {}, error: 'reference-no-urls' };
  }
  if (req.ref_transport === 'edits') {
    return { ok: false, unsupported: true, statusCode: 0, b64: null, headers: {}, body: {}, error: 'reference-edit-unsupported' };
  }
  if (req.ref_transport !== 'gemini') {
    return { ok: false, unsupported: true, statusCode: 0, b64: null, headers: {}, body: {}, error: 'reference-transport-unknown' };
  }
  try {
    const content = [{ type: 'text', text: req.prompt }];
    for (const u of urls) content.push({ type: 'image_url', image_url: { url: u } });
    const res = await httpRequest({
      method: 'POST',
      url: 'http://litellm:4000/v1/chat/completions',
      headers: { Authorization: 'Bearer ' + key },
      body: { model: req.primary_model, messages: [{ role: 'user', content: content }] },
      json: true,
      returnFullResponse: true,
      timeout: Math.max(5000, Math.min(PER_CALL_TIMEOUT_MS, remaining()))
    });
    const sc = res.statusCode || 200;
    let b64 = null;
    try {
      const msg = res.body && res.body.choices && res.body.choices[0] && res.body.choices[0].message;
      const img = msg && msg.images && msg.images[0] && msg.images[0].image_url && msg.images[0].image_url.url;
      if (img) b64 = String(img).replace(/^data:[^;]+;base64,/, '');
    } catch (e2) { b64 = null; }
    return { ok: sc >= 200 && sc < 300 && !!b64, statusCode: sc, b64: b64, headers: res.headers || {}, body: res.body || {} };
  } catch (e) {
    const sc = (e && (e.statusCode || e.httpCode || (e.response && e.response.statusCode))) || 0;
    const msg = (e && (e.message || (e.error && e.error.message))) || String(e);
    return { ok: false, statusCode: sc, b64: null, headers: {}, body: {}, error: msg };
  }
};

const worker = async function(req) {
  let att, model_used = req.primary_model, fell_back = false, used_reference = false, degrade_reason = '';
  let pin = req.primary_pin, pout = req.primary_pout, floor = req.primary_floor;
  // Reference path (ADR-052 Block 4a): try the image-to-image call first; on failure/unsupported with
  // time remaining, fail soft to plain text-to-image on the SAME tier model (no model-forcing).
  if (req.use_reference && req.ref_transport === 'edits') {
    // ADR-052 Block 4b: the gpt-image-2 /v1/images/edits multipart call ran UPSTREAM in the dedicated
    // HTTP Request node sub-workflow (Run gpt-image-2 Edit); its base64 image rides on req.edit_b64
    // (Attach Edit b64), because multipart binary cannot be sent from this Code node (Block 0).
    if (req.edit_b64) {
      att = { ok: true, statusCode: 200, b64: req.edit_b64, headers: (req.edit_header_cost != null) ? { 'x-litellm-response-cost': req.edit_header_cost } : {}, body: {} };
      used_reference = true;
    } else {
      // edit leg failed/unavailable -> fail soft to plain text-to-image on the SAME tier model.
      degrade_reason = 'reference-unanchored';
      att = (remaining() > MIN_REMAINING_FOR_CALL_MS) ? await callImage(req.primary_model, req) : { ok: false, statusCode: 0, b64: null, headers: {}, body: {}, error: 'reference-edit-failed' };
    }
  } else if (req.use_reference) {
    const refAtt = await callImageReference(req);
    if (refAtt.ok) {
      att = refAtt; used_reference = true;
    } else {
      degrade_reason = (refAtt.error === 'reference-edit-unsupported') ? 'reference-edit-unsupported' : 'reference-unanchored';
      att = (remaining() > MIN_REMAINING_FOR_CALL_MS) ? await callImage(req.primary_model, req) : refAtt;
    }
  } else {
    att = await callImage(req.primary_model, req);
  }
  // Existing one-tier-below fallback (unchanged): only when the (plain or reference-degraded) primary failed.
  if (!att.ok && remaining() > MIN_REMAINING_FOR_CALL_MS) {
    const fbModel = (req.fallback_model && req.fallback_model !== '') ? req.fallback_model : req.primary_model;
    const fb2 = await callImage(fbModel, req);
    if (fb2.ok) {
      att = fb2; model_used = fbModel; used_reference = false;
      if (fbModel !== req.primary_model) { fell_back = true; pin = req.fallback_pin; pout = req.fallback_pout; floor = req.fallback_floor; }
    }
  }
  let header_cost = null, itok = 0, otok = null;
  if (att.ok) {
    const usage = (att.body && att.body.usage) || {};
    const o = (usage.output_tokens != null) ? usage.output_tokens : ((usage.completion_tokens != null) ? usage.completion_tokens : ((usage.total_tokens != null) ? usage.total_tokens : null));
    otok = (o != null) ? Number(o) : null;
    const ii = (usage.input_tokens != null) ? usage.input_tokens : ((usage.prompt_tokens != null) ? usage.prompt_tokens : 0);
    itok = (ii != null) ? Number(ii) : 0;
    const ch = att.headers['x-litellm-response-cost'];
    header_cost = (ch != null && ch !== '') ? Number(ch) : null;
  }
  return {
    placeholder_id: req.placeholder_id, block_order: req.block_order, caption: req.caption, alt: req.alt,
    succeeded: att.ok, b64_json: att.b64 || null, mime: 'image/png',
    model_used: model_used, fell_back: fell_back, used_reference: used_reference, degrade_reason: degrade_reason,
    header_cost: header_cost, input_tokens: itok, output_tokens: otok,
    price_in_usd_per_1k: pin, price_out_usd_per_1k: pout, floor: floor,
    size: req.size, resolution_note: req.resolution_note || '',
    error: att.ok ? '' : (att.error || ('HTTP ' + att.statusCode)), statusCode: att.statusCode,
    impact: req.impact, clickup_task_id: req.clickup_task_id, triggered_by: req.triggered_by,
    invocation_type: req.invocation_type, caller_user_id: req.caller_user_id, process_type: req.process_type
  };
};

// Synthesized result for an image not generated before the soft deadline (mirrors worker() shape,
// succeeded:false) so the placeholder stays renderable downstream and surfaces a WARN, never a throw.
const notGenerated = function(req, reason) {
  return {
    placeholder_id: req.placeholder_id, block_order: req.block_order, caption: req.caption, alt: req.alt,
    succeeded: false, b64_json: null, mime: 'image/png',
    model_used: req.primary_model, fell_back: false, used_reference: false, degrade_reason: '',
    header_cost: null, input_tokens: 0, output_tokens: null,
    price_in_usd_per_1k: req.primary_pin, price_out_usd_per_1k: req.primary_pout, floor: req.primary_floor,
    size: req.size, resolution_note: req.resolution_note || '',
    error: reason, statusCode: 0,
    impact: req.impact, clickup_task_id: req.clickup_task_id, triggered_by: req.triggered_by,
    invocation_type: req.invocation_type, caller_user_id: req.caller_user_id, process_type: req.process_type
  };
};

const results = new Array(requests.length);
let idx = 0;
const next = async function() {
  if (remaining() <= 0) return;            // soft deadline passed: stop pulling new work
  const i = idx++;
  if (i >= requests.length) return;
  inFlight++; if (inFlight > maxInFlight) maxInFlight = inFlight;
  try { results[i] = await worker(requests[i]); } finally { inFlight--; }
  return next();
};
const n = Math.min(cap, requests.length);
const starters = [];
for (let k = 0; k < n; k++) starters.push(next());

// Race the bounded pool against the soft deadline; whichever resolves first we return cleanly (BELOW the
// task-runner hard kill). Calls still in flight at the deadline are clamped to finish by it (per-call
// timeout = remaining()) and then abandoned.
let deadlineTimerId = null;
const deadlineTimer = new Promise(function(resolve){ deadlineTimerId = setTimeout(function(){ resolve('deadline'); }, SOFT_DEADLINE_MS); });
await Promise.race([ Promise.all(starters), deadlineTimer ]);
if (deadlineTimerId) clearTimeout(deadlineTimerId);

// Fill any slot that never completed (deadline hit, or worker stopped pulling) as not-generated.
for (let i = 0; i < requests.length; i++) {
  if (!results[i]) { results[i] = notGenerated(requests[i], 'batch_soft_deadline'); }
}

return results.map(function(r){ r.max_in_flight = maxInFlight; r.cap = cap; return { json: r }; });

const items = $input.all().map(function(i){ return i.json; });
return items.map(function(it){
  const header = (it.header_cost != null && Number(it.header_cost) > 0) ? Number(it.header_cost) : null;
  let usd_cost = null, cost_header_missing = false;
  let input_tokens = it.input_tokens, output_tokens = it.output_tokens;
  if (header != null) { usd_cost = header; }
  else {
    cost_header_missing = true;
    if (it.output_tokens != null) { usd_cost = null; }
    else { usd_cost = (it.succeeded && it.floor != null) ? it.floor : null; input_tokens = null; output_tokens = null; }
  }
  return { json: {
    placeholder_id: it.placeholder_id, block_order: it.block_order, caption: it.caption, alt: it.alt,
    succeeded: it.succeeded, b64_json: it.b64_json, mime: it.mime, model_used: it.model_used,
    fell_back: it.fell_back, used_reference: it.used_reference, degrade_reason: it.degrade_reason,
    resolution_note: it.resolution_note, size: it.size, error: it.error,
    cost_header_missing: cost_header_missing, max_in_flight: it.max_in_flight, cap: it.cap,
    clickup_task_id: it.clickup_task_id, caller_user_id: it.caller_user_id, process_type: it.process_type,
    triggered_by: it.triggered_by, invocation_type: it.invocation_type, impact: it.impact,
    input_tokens: input_tokens, output_tokens: output_tokens, usd_cost: usd_cost,
    price_in_usd_per_1k: it.price_in_usd_per_1k, price_out_usd_per_1k: it.price_out_usd_per_1k
  } };
});

const explode = $('Explode Results').all().map(function(i){ return i.json; });
const logs = $input.all().map(function(i){ return i.json; });
const out = [];
for (let i = 0; i < explode.length; i++) {
  const e = explode[i];
  const lg = logs[i] || {};
  const cost_pln = (lg.cost_pln_total != null && !isNaN(Number(lg.cost_pln_total))) ? Number(lg.cost_pln_total) : 0;
  const success = !!(e.succeeded && e.b64_json);
  const warnings = [];
  if (!success) {
    if (e.error === 'batch_soft_deadline') warnings.push('image-batch/timeout-partial: obraz nie został wygenerowany przed limitem czasu wsadu (soft deadline) — opublikowano z zastępnikiem [obraz niedostępny]');
    else warnings.push('multimodal/image-gen-failed: ' + (e.error || 'no output'));
  }
  if (success && e.fell_back) warnings.push('image-batch/degrade: użyto modelu zapasowego o jeden poziom niżej (' + (e.model_used || '') + ')');
  if (success && e.degrade_reason === 'reference-edit-unsupported') warnings.push('image-batch/reference-edit-unsupported: obraz referencyjny dla tego priorytetu (gpt-image-2) wymaga transportu /v1/images/edits, który nie jest jeszcze podłączony (ADR-052 Blok 4b) — wygenerowano obraz bez zakotwiczenia w referencji (text-to-image)');
  if (success && e.degrade_reason === 'reference-unanchored') warnings.push('image-batch/reference-unanchored: wywołanie z obrazem referencyjnym nie powiodło się — wygenerowano obraz bez zakotwiczenia w referencji (text-to-image)');
  if (success && e.cost_header_missing) warnings.push('image-batch/cost-header-missing: brak nagłówka kosztu LiteLLM — koszt wyceniony zapasowo');
  out.push({ json: {
    placeholder_id: e.placeholder_id || '', block_order: (e.block_order != null) ? e.block_order : 99,
    success: success, b64_json: success ? (e.b64_json || null) : null, mime: e.mime || 'image/png',
    model: e.model_used || '', cost_pln: cost_pln, size: e.size || null,
    degraded: !!e.fell_back, used_reference: !!e.used_reference, cost_header_missing: !!e.cost_header_missing,
    resolution_note: e.resolution_note || '', caption: e.caption || '', alt: e.alt || '',
    warnings: warnings
  } });
}
return out;

const reqById = {};
$('Resolve Batch Requests').all().forEach(function(i){ const r = i.json || {}; if (r.placeholder_id) reqById[r.placeholder_id] = r; });
return $input.all().map(function(i){
  const s = i.json || {};
  const req = reqById[s.placeholder_id] || {};
  const b64 = (s.ok && s.b64_json) ? s.b64_json : null;
  const hc = (s.header_cost != null) ? s.header_cost : null;
  return { json: Object.assign({}, req, { edit_b64: b64, edit_header_cost: hc }) };
});
